/**
 * audio.js kernels, each module as published, in its own scope, for an
 * `AudioWorklet`, which cannot import them:
 * - `@audio/effect-subbass` 1.2.0 (MIT, Dmitry Iv.): `subbass`
 */
export const BASS_ENHANCER_KERNELS = `const subbass = (() => {
/**
 * Psychoacoustic bass enhancer (MaxxBass/RBass class) — extract the band below cutoff,
 * generate its harmonic series with an even/odd waveshaper, band-limit the harmonics to
 * the audible low-mids, and mix against dry. Small speakers reproduce the harmonics; the
 * ear reconstructs the missing fundamental.
 */

let { sin, tanh, PI } = Math

// state-variable filter tick: returns [lp, bp, hp], mutates s = {l, b}
function svf (s, x, f, q) {
	s.l += f * s.b
	let h = x - s.l - q * s.b
	s.b += f * h
	return [s.l, s.b, h]
}

function subbass (data, params = {}) {
	let fc = params.fc ?? params.freq ?? 80  // sub cutoff, Hz — harmonics built from below here (\`freq\`: former name)
	let amount = params.amount ?? 0.5        // harmonic level 0..1
	let drive = params.drive ?? 0.5          // waveshaper intensity 0..1
	let keep = params.keep ?? 1              // how much original sub to keep (0 = replace)
	let fs = params.fs || 44100

	if (!params._sub) {
		params._sub = { l: 0, b: 0 }           // sub extraction LP
		params._out = { l: 0, b: 0 }           // harmonic band BP
		params._dc = 0
	}
	let f1 = 2 * sin(PI * Math.min(fc, fs / 4) / fs)
	let f2 = 2 * sin(PI * Math.min(fc * 2.5, fs / 4) / fs)
	let g = 1 + drive * 6
	let aDc = 1 - Math.exp(-2 * PI * 10 / fs)

	for (let i = 0, l = data.length; i < l; i++) {
		let x = data[i]
		let [sub] = svf(params._sub, x, f1, 1.2)
		// even harmonics from |x| rectification + odd from tanh — full series
		let h = tanh(sub * g) * 0.6 + Math.abs(sub) * g * 0.4
		params._dc += aDc * (h - params._dc)   // DC-block the rectifier output
		h -= params._dc
		// keep harmonics in the speaker-friendly band around 2–5× fc
		svf(params._out, h, f2, 0.8)
		let harm = params._out.b               // bandpass output
		data[i] = x - (1 - keep) * sub + amount * 2 * harm
	}
	return data
}

return subbass;
})();
`;

/**
 * audio.js kernels, each module as published, in its own scope, for an
 * `AudioWorklet`, which cannot import them:
 * - `@audio/spatial-binaural` 0.1.1 (MIT, Dmitry Iv.): `binaural`
 */
export const BINAURAL_PANNER_KERNELS = `const binaural = (() => {
/**
 * Structural binaural panner — spherical-head ITD + head-shadow ILD synthesis.
 * Collapses the input to mono (mid), places it in space, writes L/R in place.
 * No HRIR data: azimuth cues only (elevation/pinna is out of scope, see README).
 *
 * C. P. Brown & R. O. Duda, "A Structural Model for Binaural Sound Synthesis,"
 * IEEE Trans. Speech and Audio Processing, 6(5), pp. 476-488, 1998.
 *  - ITD: eq. (2) (p. 477), the Woodworth/Schlosberg two-branch delay.
 *  - ILD: eq. (3)-(5) (p. 477), the one-pole-one-zero head-shadow filter and
 *    its alpha(theta) sweep — alpha_min=0.1, theta_min=150 deg, confirmed
 *    against the published equations (not the task-supplied guess: verified
 *    directly against the paper's text/figures).
 *  - Each ear's incidence angle is measured from the geometric interaural
 *    axis (+-90 deg from front) — the convention eq. (2)-(5) are stated in.
 *    The paper's fuller eq. (6) instead anchors ears at the measured ear-
 *    canal entrance (+-100 deg) when combining with their pinna model; that
 *    refinement is skipped along with elevation (below).
 *  - Elevation (pinna echoes): Brown-Duda eq. (8) + Table I give a 6-tap
 *    reflection model, but its scaling factor D_n was fit per-subject (only
 *    two listeners), not a general physical constant, and the paper itself
 *    flags the fit as failing near 90 deg elevation ("needs further
 *    investigation and verification"). Baking someone else's individual
 *    calibration in as a fake default would misrepresent it as physics, so
 *    this atom stays azimuth-only (v1) rather than invent a generic D_n.
 */

let { cos, PI, abs, min, max, exp, ceil } = Math

const C_SOUND = 343       // speed of sound, m/s
const ALPHA_MIN = 0.1     // eq. (5)
const THETA_MIN = 150     // eq. (5), degrees
const AZ_SMOOTH_TAU = 0.005   // s — one-pole time constant smoothing azimuth jumps

// Shortest angular distance on a circle, degrees, folded into incidence-angle range [0, 180].
function angDist (a, b) {
	let d = abs(a - b) % 360
	return d > 180 ? 360 - d : d
}

// Woodworth/Brown-Duda per-ear delay, eq. (2). thetaDeg = angle of incidence at this ear, [0,180].
function itd (thetaDeg, headRadius) {
	let th = thetaDeg * PI / 180
	return th < PI / 2 ? -(headRadius / C_SOUND) * cos(th) : (headRadius / C_SOUND) * (th - PI / 2)
}

// Brown-Duda eq. (5): head-shadow shelf amount, sweeps 2 (ipsilateral boost) -> alpha_min (contralateral cut).
function alpha (thetaDeg) {
	return (1 + ALPHA_MIN / 2) + (1 - ALPHA_MIN / 2) * cos(thetaDeg / THETA_MIN * PI)
}

/**
 * One-pole-one-zero head-shadow filter (eq. 3), discretized by direct
 * bilinear transform s = 2fs(1-z^-1)/(1+z^-1) (no frequency prewarp: the
 * pole/zero base omega0 sits well below Nyquist at audio rates, so the warp
 * error is negligible for a perceptual model). With K = 2*omega0 = 2c/a and
 * kappa = 2fs:
 *   H(s) = (1 + alpha*s/(2*omega0)) / (1 + s/(2*omega0))
 *   (K + alpha*s)/(K + s), substitute s, multiply num/denom by (1+z^-1):
 *   => b0 = (K + alpha*kappa)/(K + kappa)
 *      b1 = (K - alpha*kappa)/(K + kappa)
 *      a1 = (K - kappa)/(K + kappa)
 *   y[n] = b0*x[n] + b1*x[n-1] - a1*y[n-1]
 * DC gain is exactly 1 (no shadow at 0 Hz, for any alpha); gain at Nyquist
 * -> alpha, matching the continuous filter's high-frequency asymptote.
 */
function headShadow (x, a, K, kappa, st) {
	let b0 = (K + a * kappa) / (K + kappa)
	let b1 = (K - a * kappa) / (K + kappa)
	let a1 = (K - kappa) / (K + kappa)
	let y = b0 * x + b1 * st.x1 - a1 * st.y1
	st.x1 = x; st.y1 = y
	return y
}

/**
 * @param {Float64Array} left - modified in place
 * @param {Float64Array} right - modified in place
 * @param {object} params - { azimuth: deg -180..180 (0 front, +right) default 0,
 *   distance: m default 1, headRadius: m default 0.0875, mix: 0..1 default 1, fs }
 */
function binaural (left, right, params) {
	let azimuth = params.azimuth ?? 0
	let distance = params.distance ?? 1
	let headRadius = params.headRadius ?? 0.0875
	let mix = params.mix ?? 1
	let fs = params.fs || 44100

	if (mix <= 0) return [left, right]   // identity — skip the wet path entirely (bit-exact)

	// Delay ring sized from the physics: max |ITD| = (a/c)(1 + pi/2), plus headroom.
	let ringSize = max(8, ceil((headRadius / C_SOUND) * (1 + PI / 2) * fs) + 4)
	if (!params._ring || params._ring.length < ringSize) {
		params._ring = new Float64Array(ringSize)
		params._wp = 0
	}
	let ring = params._ring, n = ring.length, wp = params._wp
	let filtL = params._filtL ?? (params._filtL = { x1: 0, y1: 0 })
	let filtR = params._filtR ?? (params._filtR = { x1: 0, y1: 0 })
	if (params._az == null) params._az = azimuth   // snap on first use — nothing to smooth from yet
	let az = params._az
	let azK = 1 - exp(-1 / (AZ_SMOOTH_TAU * fs))    // one-pole coefficient, click-free azimuth jumps

	let K = 2 * C_SOUND / headRadius   // head-shadow base frequency * 2 (eq. 4: omega0 = c/a)
	let kappa = 2 * fs                 // bilinear-transform constant
	let distGain = 1 / (distance || 1)

	for (let i = 0, l = left.length; i < l; i++) {
		let dryL = left[i], dryR = right[i]
		let mid = (dryL + dryR) * 0.5 * distGain

		az += (azimuth - az) * azK   // smoothed azimuth — everything below tracks this, not the raw target

		let thR = angDist(az, 90), thL = angDist(az, -90)
		let tR = itd(thR, headRadius), tL = itd(thL, headRadius)
		let tMin = min(tR, tL)                  // nearer ear normalized to zero added latency
		let dR = (tR - tMin) * fs, dL = (tL - tMin) * fs

		ring[wp] = mid

		let readR = ((wp - dR) % n + n) % n
		let readL = ((wp - dL) % n + n) % n
		let r0 = readR | 0, rf = readR - r0, r1 = (r0 + 1) % n
		let l0 = readL | 0, lf = readL - l0, l1 = (l0 + 1) % n
		let xR = ring[r0] * (1 - rf) + ring[r1] * rf
		let xL = ring[l0] * (1 - lf) + ring[l1] * lf

		let wetR = headShadow(xR, alpha(thR), K, kappa, filtR)
		let wetL = headShadow(xL, alpha(thL), K, kappa, filtL)

		left[i] = dryL * (1 - mix) + wetL * mix
		right[i] = dryR * (1 - mix) + wetR * mix

		wp = (wp + 1) % n
	}

	params._az = az
	params._wp = wp
	return [left, right]
}

return binaural;
})();
`;

/**
 * audio.js kernels, each module as published, in its own scope, for an
 * `AudioWorklet`, which cannot import them:
 * - `@audio/effect-chorus` 2.0.2 (MIT, Dmitry Iv.): `chorus`
 */
export const CHORUS_KERNELS = `const chorus = (() => {
/**
 * Chorus — multiple detuned delay lines for ensemble thickening
 */

let {sin, floor, PI} = Math

function chorus (data, params = {}) {
	let rate = params.rate == null ? 1.5 : params.rate
	let depth = params.depth == null ? 0.5 : params.depth
	let delay = params.delay == null ? 0.02 : params.delay  // seconds
	let voices = Math.max(1, (params.voices || 3) | 0)  // integer ≥ 1 — wet/voices below
	let fs = params.fs || 44100

	let maxDelay = Math.max(1, Math.floor(delay * 2 * fs))
	let delaySamples = delay * fs

	if (!params.buffer || params.buffer.length < maxDelay) {
		params.buffer = new Float64Array(maxDelay)
		params.ptr = 0
	}
	// voices can change live — a short phase array would feed NaN into the LFOs
	if (!params._phases || params._phases.length !== voices) {
		params._phases = new Float64Array(voices)
		for (let v = 0; v < voices; v++) params._phases[v] = v / voices * 2 * PI
	}
	let buf = params.buffer, ptr = params.ptr, phases = params._phases
	if (ptr >= maxDelay) ptr = 0  // delay shrank live — re-enter the active ring
	let inc = 2 * PI * rate / fs

	for (let i = 0, l = data.length; i < l; i++) {
		let x = data[i]
		buf[ptr] = x

		let wet = 0
		for (let v = 0; v < voices; v++) {
			let d = delaySamples * (1 + depth * sin(phases[v]))
			phases[v] += inc
			if (phases[v] > 2 * PI) phases[v] -= 2 * PI

			// total wrap — d may reach/exceed maxDelay (depth ≈ 1 vs floored buffer size)
			let readPos = ((ptr - d) % maxDelay + maxDelay) % maxDelay

			let idx = floor(readPos)
			let frac = readPos - idx
			let a = buf[idx % maxDelay]
			let b = buf[(idx + 1) % maxDelay]
			wet += a + frac * (b - a)
		}

		ptr = (ptr + 1) % maxDelay
		data[i] = (x + wet / voices) * 0.5
	}

	params.ptr = ptr

	return data
}

return chorus;
})();
`;

/**
 * audio.js kernels, each module as published, in its own scope, for an
 * `AudioWorklet`, which cannot import them:
 * - `@audio/dynamics-envelope` 0.1.4 (MIT, Dmitry Iv.): `timeCoef`, as `module0`
 * - `@audio/dynamics-envelope` 0.1.4 (MIT, Dmitry Iv.): `envelope`, as `module1`
 * - `@audio/dynamics-compand` 0.1.7 (MIT, Dmitry Iv.): `writer`, `concat`, `db2lin`, `lin2db`, as `module2`
 * - `@audio/dynamics-compand` 0.1.7 (MIT, Dmitry Iv.): `compandStream`, as `module3`
 * - `@audio/dynamics-compand` 0.1.7 (MIT, Dmitry Iv.): `compand`
 */
export const COMPANDER_KERNELS = `const module0 = (() => {
// Local helpers (inlined family convention — no shared-dep package).

// One-pole smoothing coefficient: y[n] = c·y[n-1] + (1-c)·x[n]. ms → coefficient.
function timeCoef(ms, sampleRate) {
  if (ms <= 0) return 0
  return Math.exp(-1 / (ms * 0.001 * sampleRate))
}

return { timeCoef };
})();

const module1 = (() => {
const { timeCoef } = module0;

// Branching one-pole envelope follower. Returns a stateful per-sample detector.
// Separate attack and release time constants; the classic feed-forward compressor
// topology. Peak or RMS detection selectable.
function envelope(opts = {}) {
  // sampleRate is this family's documented key; fs accepted too — half the ecosystem
  // (and dynamics' own fs-named atoms: multiband, leveler, transient-shaper) passes fs,
  // and silently falling back to 44100 skews ballistics at any other rate.
  let sr = opts.sampleRate ?? opts.fs ?? 44100
  let aa = timeCoef(opts.attack ?? 5, sr)
  let ar = timeCoef(opts.release ?? 50, sr)
  let detector = opts.detector || 'peak'
  let rmsWin = Math.max(1, opts.rmsWindow || 256)

  let rmsBuf = detector === 'rms' ? new Float32Array(rmsWin) : null
  let rmsSum = 0
  let rmsIdx = 0
  let env = 0

  return function detect(x) {
    let mag
    if (detector === 'rms') {
      let sq = x * x
      rmsSum += sq - rmsBuf[rmsIdx]
      rmsBuf[rmsIdx] = sq
      rmsIdx = (rmsIdx + 1) % rmsWin
      mag = Math.sqrt(Math.max(0, rmsSum / rmsWin))
    } else {
      mag = x < 0 ? -x : x
    }
    let c = mag > env ? aa : ar
    env = c * env + (1 - c) * mag
    return env
  }
}

return { envelope };
})();

const module2 = (() => {
// Local helpers (inlined family convention — no shared-dep package).

// Wrap { write, flush } into a single callable: write(chunk) → process, write() → flush.
function writer(s) {
  return (chunk) => chunk ? s.write(chunk) : s.flush()
}

function concat(a, b) {
  if (!b || !b.length) return a
  if (!a.length) return b
  let out = new Float32Array(a.length + b.length)
  out.set(a)
  out.set(b, a.length)
  return out
}

// e^(dB·ln10/20) and ln·20/ln10, not 10^(dB/20) and 20·log10: half the cost in V8 (exp and log take ~9 ns, pow
// and log10 ~17-19), a few double ulps from them, far under a float32 ulp.
const db2lin = (db) => Math.exp(db * (Math.LN10 / 20))

const lin2db = (lin) => 20 / Math.LN10 * Math.log(Math.max(Math.abs(lin), 1e-10))

return { writer, concat, db2lin, lin2db };
})();

const module3 = (() => {
const { envelope } = module1;
const { writer, concat, db2lin, lin2db } = module2;

// Multi-segment compander (SoX \`compand\`). Arbitrary piecewise-linear transfer
// in dB. A single curve unifies compression, expansion and gating: points below
// the identity line reduce loud parts; points above raise quiet parts.
function compand(data, opts) {
  if (!(data instanceof Float32Array)) return writer(compandStream(data))
  let s = compandStream(opts)
  return concat(s.write(data), s.flush())
}

function compandStream(opts = {}) {
  // Points: [[inDb, outDb], ...]. Default = mild compression above -20 dB.
  let points = (opts.points || [[-90, -90], [-60, -60], [-20, -20], [0, -8]])
    .slice().sort((a, b) => a[0] - b[0])
  let env = envelope({ ...opts, attack: opts.attack ?? 5, release: opts.release ?? 200 })

  return {
    write(chunk) {
      let out = new Float32Array(chunk.length)
      for (let i = 0; i < chunk.length; i++) {
        let x = chunk[i]
        let lvl = lin2db(env(x))
        let mapped = transfer(points, lvl)
        out[i] = x * db2lin(mapped - lvl)
      }
      return out
    },
    flush() { return new Float32Array(0) }
  }
}

function transfer(points, x) {
  if (x <= points[0][0]) return points[0][1] + (x - points[0][0])
  if (x >= points[points.length - 1][0]) {
    let [xE, yE] = points[points.length - 1]
    return yE + (x - xE)
  }
  for (let i = 1; i < points.length; i++) {
    let [x1, y1] = points[i]
    if (x <= x1) {
      let [x0, y0] = points[i - 1]
      let t = (x - x0) / (x1 - x0)
      return y0 + t * (y1 - y0)
    }
  }
  return x
}

return { compandStream, default: compand };
})();

const compand = (() => {
const { compandStream } = module3;
// atom manifest — wraps the SoX-style compand kernel per @audio/compile CONTRACT.
// The kernel's transfer curve is an arbitrary array of [inDb, outDb] points — arrays
// aren't a valid CONTRACT param type (number/enum/bool only). Scalarized: the input
// breakpoints stay fixed at the kernel's own default shape (-90/-60/-20/0 dB) and the
// four output levels become restart-flagged number params, assembled into a \`points\`
// array only at construction (stream-per-channel style, like the gate pilot).

const IN_DB = [-90, -60, -20, 0]

const compand = (ctx) => {
	const streams = []
	const opts = {
		sampleRate: ctx.sampleRate,
		points: IN_DB.map((inDb, i) => [inDb, ctx.params[\`out\${i}\`][0]]),
		attack: ctx.params.attack[0],
		release: ctx.params.release[0],
	}
	for (let c = 0, N = ctx.maxChannels ?? 8; c < N; c++) streams.push(compandStream(opts))
	return (inputs, outputs) => {
		const inp = inputs[0], out = outputs[0]
		if (!inp || !inp.length) return
		for (let c = 0; c < inp.length; c++) out[c].set(streams[c].write(inp[c]))
	}
}
compand.channels = 'any'
compand.tail = 0
compand.params = {
	out0:    { type: 'number', min: -90, max: 0, default: -90, unit: 'dB', flags: ['restart'] },
	out1:    { type: 'number', min: -90, max: 0, default: -60, unit: 'dB', flags: ['restart'] },
	out2:    { type: 'number', min: -90, max: 0, default: -20, unit: 'dB', flags: ['restart'] },
	out3:    { type: 'number', min: -90, max: 0, default: -8, unit: 'dB', flags: ['restart'] },
	attack:  { type: 'number', min: 0.1, max: 200, default: 5, unit: 'ms', flags: ['restart'] },
	release: { type: 'number', min: 1, max: 2000, default: 200, unit: 'ms', flags: ['restart'] },
}

return compand;
})();
`;

/**
 * audio.js kernels, each module as published, in its own scope, for an
 * `AudioWorklet`, which cannot import them:
 * - `@audio/dynamics-envelope` 0.1.4 (MIT, Dmitry Iv.): `timeCoef`, as `module0`
 * - `@audio/dynamics-envelope` 0.1.4 (MIT, Dmitry Iv.): `envelope`, as `module1`
 * - `@audio/dynamics-compressor` 0.2.1 (MIT, Dmitry Iv.): `writer`, `concat`, `db2lin`, `lin2db`, as `module2`
 * - `@audio/dynamics-compressor` 0.2.1 (MIT, Dmitry Iv.): `compressorGain`, as `module3`
 * - `@audio/dynamics-vca` 0.2.5 (MIT, Dmitry Iv.): `writer`, `concat`, `db2lin`, `lin2db`, `timeCoef`, as `module4`
 * - `@audio/dynamics-vca` 0.2.5 (MIT, Dmitry Iv.): `vcaStream`, as `module5`
 * - `@audio/dynamics-vca` 0.2.5 (MIT, Dmitry Iv.): `vca`
 * - `@audio/dynamics-fet` 0.2.5 (MIT, Dmitry Iv.): `writer`, `concat`, `db2lin`, `lin2db`, `timeCoef`, as `module7`
 * - `@audio/dynamics-fet` 0.2.5 (MIT, Dmitry Iv.): `fetStream`, as `module8`
 * - `@audio/dynamics-fet` 0.2.5 (MIT, Dmitry Iv.): `fet`
 * - `@audio/dynamics-opto` 0.2.5 (MIT, Dmitry Iv.): `writer`, `concat`, `db2lin`, `lin2db`, `timeCoef`, as `module10`
 * - `@audio/dynamics-opto` 0.2.5 (MIT, Dmitry Iv.): `optoStream`, as `module11`
 * - `@audio/dynamics-opto` 0.2.5 (MIT, Dmitry Iv.): `opto`
 * - `@audio/dynamics-varimu` 0.2.4 (MIT, Dmitry Iv.): `writer`, `concat`, `db2lin`, `lin2db`, `timeCoef`, as `module13`
 * - `@audio/dynamics-varimu` 0.2.4 (MIT, Dmitry Iv.): `varimuStream`, as `module14`
 * - `@audio/dynamics-varimu` 0.2.4 (MIT, Dmitry Iv.): `varimu`
 * - `@audio/dynamics-compressor` 0.3.1 (MIT, Dmitry Iv.): `writer`, `concat`, `db2lin`, `lin2db`, `timeCoef`, as `module16`
 * - `@audio/dynamics-compressor` 0.3.1 (MIT, Dmitry Iv.): `compress`, `compressorState`, as `module17`
 * - `@audio/dynamics-compressor` 0.3.1 (MIT, Dmitry Iv.): `compressor`
 */
export const COMPRESSOR_KERNELS = `const module0 = (() => {
// Local helpers (inlined family convention — no shared-dep package).

// One-pole smoothing coefficient: y[n] = c·y[n-1] + (1-c)·x[n]. ms → coefficient.
function timeCoef(ms, sampleRate) {
  if (ms <= 0) return 0
  return Math.exp(-1 / (ms * 0.001 * sampleRate))
}

return { timeCoef };
})();

const module1 = (() => {
const { timeCoef } = module0;

// Branching one-pole envelope follower. Returns a stateful per-sample detector.
// Separate attack and release time constants; the classic feed-forward compressor
// topology. Peak or RMS detection selectable.
function envelope(opts = {}) {
  // sampleRate is this family's documented key; fs accepted too — half the ecosystem
  // (and dynamics' own fs-named atoms: multiband, leveler, transient-shaper) passes fs,
  // and silently falling back to 44100 skews ballistics at any other rate.
  let sr = opts.sampleRate ?? opts.fs ?? 44100
  let aa = timeCoef(opts.attack ?? 5, sr)
  let ar = timeCoef(opts.release ?? 50, sr)
  let detector = opts.detector || 'peak'
  let rmsWin = Math.max(1, opts.rmsWindow || 256)

  let rmsBuf = detector === 'rms' ? new Float32Array(rmsWin) : null
  let rmsSum = 0
  let rmsIdx = 0
  let env = 0

  return function detect(x) {
    let mag
    if (detector === 'rms') {
      let sq = x * x
      rmsSum += sq - rmsBuf[rmsIdx]
      rmsBuf[rmsIdx] = sq
      rmsIdx = (rmsIdx + 1) % rmsWin
      mag = Math.sqrt(Math.max(0, rmsSum / rmsWin))
    } else {
      mag = x < 0 ? -x : x
    }
    let c = mag > env ? aa : ar
    env = c * env + (1 - c) * mag
    return env
  }
}

return { envelope };
})();

const module2 = (() => {
// Local helpers (inlined family convention — no shared-dep package).

const db2lin = (db) => Math.pow(10, db / 20)

const lin2db = (lin) => 20 * Math.log10(Math.max(Math.abs(lin), 1e-10))

// Wrap { write, flush } into a single callable: write(chunk) → process, write() → flush.
function writer(s) {
  return (chunk) => chunk ? s.write(chunk) : s.flush()
